css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); display: flex; align-items: flex-end; gap: 3%; }
.loader span { position: relative; flex: 1; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent), var(--accent-2)); }
.loader span::after { content: ''; position: absolute; inset: 14% 16% 8%; background: repeating-linear-gradient(to bottom, color-mix(in srgb, #fff 82%, transparent) 0 8%, transparent 8% 22%); -webkit-mask: repeating-linear-gradient(to right, #000 0 34%, transparent 34% 68%); mask: repeating-linear-gradient(to right, #000 0 34%, transparent 34% 68%); animation: windows calc(var(--loader-speed) * 1.6) steps(2, end) infinite; }
.loader span:nth-child(1) { height: 54%; }
.loader span:nth-child(2) { height: 80%; }
.loader span:nth-child(3) { height: 100%; }
.loader span:nth-child(4) { height: 66%; }
.loader span:nth-child(5) { height: 88%; }
.loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(4)::after { animation-delay: calc(var(--loader-speed) * .9); }
.loader span:nth-child(5)::after { animation-delay: calc(var(--loader-speed) * 1.2); }
@keyframes windows { 0% { opacity: .28; } 50% { opacity: 1; } 100% { opacity: .28; } }
